node -e "
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle } = require('docx');
const fs = require('fs');

const products = [
  { id: 'PROD-B98D14', name: 'Anker Portable Bluetooth Speaker', category: 'Electronics', price: '\$79', stock: 'Yes' },
  { id: 'PROD-FA0948', name: 'LogiTech Wireless Mouse M310', category: 'Electronics', price: '\$29', stock: 'Yes' },
];

const borderStyle = { style: BorderStyle.SINGLE, size: 1, color: '999999' };
const cellBorders = { top: borderStyle, bottom: borderStyle, left: borderStyle, right: borderStyle };

function headerCell(text) {
  return new TableCell({
    borders: cellBorders,
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, size: 22, font: 'Arial' })] })],
  });
}

function dataCell(text) {
  return new TableCell({
    borders: cellBorders,
    children: [new Paragraph({ children: [new TextRun({ text, size: 22, font: 'Arial' })] })],
  });
}

const table = new Table({
  width: { size: 100, type: WidthType.PERCENTAGE },
  rows: [
    new TableRow({ children: ['Product ID', 'Name', 'Category', 'Price', 'In Stock'].map(h => headerCell(h)) }),
    ...products.map(p => new TableRow({ children: [dataCell(p.id), dataCell(p.name), dataCell(p.category), dataCell(p.price), dataCell(p.stock)] })),
  ],
});

const doc = new Document({
  sections: [{
    children: [
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 200 },
        children: [new TextRun({ text: 'Inventory Summary', bold: true, size: 36, font: 'Arial' })],
      }),
      new Paragraph({
        spacing: { after: 200 },
        children: [new TextRun({ text: 'Date: 2026-09-02', size: 22, font: 'Arial', italics: true })],
      }),
      new Paragraph({
        spacing: { after: 200 },
        children: [new TextRun({
          text: 'This document provides a brief inventory summary for two selected products from the product inventory catalog (product_inventory.xlsx).',
          size: 22, font: 'Arial',
        })],
      }),
      table,
      new Paragraph({ spacing: { before: 300, after: 100 }, children: [new TextRun({ text: 'Summary', bold: true, size: 28, font: 'Arial' })] }),
      new Paragraph({
        spacing: { after: 100 },
        children: [new TextRun({
          text: 'Both products fall under the Electronics category and are currently marked as In Stock:',
          size: 22, font: 'Arial',
        })],
      }),
      new Paragraph({
        bullet: { level: 0 },
        children: [new TextRun({ text: 'Anker Portable Bluetooth Speaker', bold: true, size: 22, font: 'Arial' }), new TextRun({ text: ' — priced at \$79.', size: 22, font: 'Arial' })],
      }),
      new Paragraph({
        bullet: { level: 0 },
        children: [new TextRun({ text: 'LogiTech Wireless Mouse M310', bold: true, size: 22, font: 'Arial' }), new TextRun({ text: ' — priced at \$29.', size: 22, font: 'Arial' })],
      }),
      new Paragraph({
        spacing: { before: 200 },
        children: [new TextRun({
          text: 'No supply concerns at this time. Both items are available for order fulfillment.',
          size: 22, font: 'Arial',
        })],
      }),
    ],
  }],
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/workspace/data/inventory_summary.docx', buf);
  console.log('Word document saved successfully. Size:', buf.length, 'bytes');
});
"
